local BlacksmithViseMaker = {}
local PRODUCTS = {
    iron_blacksmithvise = { name = "Železni kovaška primernica", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kovaška primernica za kovace." },
    bronze_blacksmithvise = { name = "Bronast kovaška primernica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kovaška primernica za kovace." },
    silver_blacksmithvise = { name = "Srebrn kovaška primernica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kovaška primernica za kovace." },
    gilded_blacksmithvise = { name = "Pozlačen kovaška primernica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kovaška primernica za kovace." },
    jewel_set_blacksmithvise = { name = "Draguljast kovaška primernica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kovaška primernica za kovace." },
    royal_sovereign_blacksmithvise = { name = "Kraljevski suveren kovaška primernica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kovaška primernica z biseri za krono." },
}
local BUILDINGS = {
    blacksmithvise_workshop = { name = "Blacksmithvise delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    blacksmithvise_house = { name = "Blacksmithvise hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_blacksmithvise_atelier = { name = "Mojstrski blacksmithvise atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_blacksmithvise_palace = { name = "Suverena blacksmithvise palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BlacksmithViseMaker.ironStock=18; BlacksmithViseMaker.bronzeStock=14; BlacksmithViseMaker.woodStock=10; BlacksmithViseMaker.leatherStock=8; BlacksmithViseMaker.silverStock=8; BlacksmithViseMaker.goldStock=6; BlacksmithViseMaker.jewelStock=4; BlacksmithViseMaker.pearlStock=4
BlacksmithViseMaker.productStock = {}; BlacksmithViseMaker.buildings = {}; BlacksmithViseMaker.maker = nil; BlacksmithViseMaker.activeMaking = {}; BlacksmithViseMaker.totalProducts = 0; BlacksmithViseMaker.dayTimer = 0
function BlacksmithViseMaker.init() BlacksmithViseMaker.ironStock=18; BlacksmithViseMaker.bronzeStock=14; BlacksmithViseMaker.woodStock=10; BlacksmithViseMaker.leatherStock=8; BlacksmithViseMaker.silverStock=8; BlacksmithViseMaker.goldStock=6; BlacksmithViseMaker.jewelStock=4; BlacksmithViseMaker.pearlStock=4; BlacksmithViseMaker.productStock={}; BlacksmithViseMaker.buildings={}; BlacksmithViseMaker.maker=nil; BlacksmithViseMaker.activeMaking={}; BlacksmithViseMaker.totalProducts=0; BlacksmithViseMaker.dayTimer=0; print("[BlacksmithViseMaker] Royal Blacksmith Vise Maker System initialized (6 products, 4 buildings)") end
function BlacksmithViseMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BlacksmithViseMaker.maker={name=n or ("Primernik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Primernik najet: %s (spretnost: %d)",BlacksmithViseMaker.maker.name,s),"success") end; return true end
function BlacksmithViseMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BlacksmithViseMaker.build(id) local ok,e=BlacksmithViseMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BlacksmithViseMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BlacksmithViseMaker.getQualityBonus() local b=0; for _,bd in ipairs(BlacksmithViseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BlacksmithViseMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BlacksmithViseMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BlacksmithViseMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BlacksmithViseMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BlacksmithViseMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BlacksmithViseMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BlacksmithViseMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BlacksmithViseMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BlacksmithViseMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BlacksmithViseMaker.buildings==0 then return false,"Potrebna primerniška delavnica" end; if not BlacksmithViseMaker.maker then return false,"Potreben primernik" end; return true end
function BlacksmithViseMaker.make(pt,qty) qty=qty or 1; local ok,e=BlacksmithViseMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BlacksmithViseMaker.ironStock=BlacksmithViseMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BlacksmithViseMaker.bronzeStock=BlacksmithViseMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BlacksmithViseMaker.woodStock=BlacksmithViseMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BlacksmithViseMaker.leatherStock=BlacksmithViseMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BlacksmithViseMaker.silverStock=BlacksmithViseMaker.silverStock-d.silverCost*qty end; if d.goldCost then BlacksmithViseMaker.goldStock=BlacksmithViseMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BlacksmithViseMaker.jewelStock=BlacksmithViseMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BlacksmithViseMaker.pearlStock=BlacksmithViseMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BlacksmithViseMaker.maker then t=math.max(1,t-math.floor(BlacksmithViseMaker.maker.skill/13)) end; table.insert(BlacksmithViseMaker.activeMaking,{id="blacksmithvise_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BlacksmithViseMaker.completeMaking(m) local q=1.0+(BlacksmithViseMaker.getQualityBonus()/100); if BlacksmithViseMaker.maker then q=q+(BlacksmithViseMaker.maker.skill/140) end; q=math.min(2.5,q); BlacksmithViseMaker.productStock[m.productType]=(BlacksmithViseMaker.productStock[m.productType] or 0)+m.quantity; BlacksmithViseMaker.totalProducts=BlacksmithViseMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BlacksmithViseMaker.maker then BlacksmithViseMaker.maker.itemsMade=BlacksmithViseMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BlacksmithViseMaker.maker.skill=math.min(100,BlacksmithViseMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Primernica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"blacksmithvise.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BlacksmithViseMaker.update(dt) if not _G.state then return end; BlacksmithViseMaker.dayTimer=BlacksmithViseMaker.dayTimer+dt; if BlacksmithViseMaker.dayTimer>=30 then BlacksmithViseMaker.dayTimer=0; for i=#BlacksmithViseMaker.activeMaking,1,-1 do local m=BlacksmithViseMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BlacksmithViseMaker.completeMaking(m); table.remove(BlacksmithViseMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BlacksmithViseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BlacksmithViseMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BlacksmithViseMaker.getStats() return {ironStock=BlacksmithViseMaker.ironStock,bronzeStock=BlacksmithViseMaker.bronzeStock,woodStock=BlacksmithViseMaker.woodStock,leatherStock=BlacksmithViseMaker.leatherStock,silverStock=BlacksmithViseMaker.silverStock,goldStock=BlacksmithViseMaker.goldStock,jewelStock=BlacksmithViseMaker.jewelStock,pearlStock=BlacksmithViseMaker.pearlStock,productStock=BlacksmithViseMaker.productStock,numBuildings=#BlacksmithViseMaker.buildings,hasMaker=BlacksmithViseMaker.maker~=nil,makerName=BlacksmithViseMaker.maker and BlacksmithViseMaker.maker.name or "—",makerSkill=BlacksmithViseMaker.maker and BlacksmithViseMaker.maker.skill or 0,activeMaking=#BlacksmithViseMaker.activeMaking,totalProducts=BlacksmithViseMaker.totalProducts} end
return BlacksmithViseMaker
